const captured=[],original=URL.createObjectURL;URL.createObjectURL=b=>{captured.push(b);return original(b)};
const click=s=>document.querySelector(s).click();click('[role=tab][data-variant="A"]');click('[data-step="3"]');click('[data-action="csv"]');click('[data-action="compare"]');click('[data-choose="B"]');click('[data-action="export"]');click('[data-action="clear"]');click('[data-action="close"]');URL.createObjectURL=original;
return Promise.all(captured.map(b=>b.text())).then(([csv,json])=>{const choice=JSON.parse(json),rows=csv.trim().split('\n').slice(1),total=rows.reduce((s,r)=>s+Number(r.split(';')[2]),0);if(rows.length!==3||total!==9600||choice.variant!=='B'||choice.prd_created!==false)throw Error('download contract');return {passed:true,csv_rows:rows.length,csv_total_RUB:total,choice_variant:choice.variant,prd_created:choice.prd_created,selection_cleared:localStorage.getItem('n3-cjm-selection-v1')===null}});
